async function adminRequestAllowed(request, env) {
  const expected = String(env.SETUP_ADMIN_KEY || "");
  const provided = String(request.headers.get("X-Azhand-Admin-Key") || "");
  if (expected && provided && constantTimeEqual(expected, provided)) return true;

  const token = bearer(request);
  if (!token || !env.DB) return false;
  try {
    await ensureAppSchema(env);
    const tokenHash = await sha256Text(token);
    const row = await env.DB.prepare(
      `SELECT token_hash FROM admin_sessions WHERE token_hash=? AND expires_at>? LIMIT 1`
    ).bind(tokenHash, new Date().toISOString()).first();
    if (!row) return false;
    try { await env.DB.prepare(`UPDATE admin_sessions SET last_seen_at=CURRENT_TIMESTAMP WHERE token_hash=?`).bind(tokenHash).run(); } catch {}
    return true;
  } catch {
    return false;
  }
}

function cleanText(value, maxLength = 200) {
  return String(value || "").replace(/\u0000/g, "").trim().slice(0, maxLength);
}

function normalizeDigits(value) {
  return String(value || "")
    .replace(/[۰-۹]/g, d => String("۰۱۲۳۴۵۶۷۸۹".indexOf(d)))
    .replace(/[٠-٩]/g, d => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)));
}

function normalizeMobile(value) {
  let digits = normalizeDigits(value).replace(/\D+/g, "");
  if (digits.startsWith("0098")) digits = "0" + digits.slice(4);
  else if (digits.startsWith("98")) digits = "0" + digits.slice(2);
  return digits.slice(0, 11);
}

function randomDigits(length = 6) {
  const bytes = new Uint8Array(length);
  crypto.getRandomValues(bytes);
  return Array.from(bytes).map(v => String(v % 10)).join("");
}

async function sha256Text(text) {
  return sha256Hex(new TextEncoder().encode(String(text || "")));
}

function constantTimeEqual(a, b) {
  const left = String(a || "");
  const right = String(b || "");
  let diff = left.length ^ right.length;
  const max = Math.max(left.length, right.length);
  for (let i = 0; i < max; i++) {
    const lc = i < left.length ? left.charCodeAt(i) : 0;
    const rc = i < right.length ? right.charCodeAt(i) : 0;
    diff |= lc ^ rc;
  }
  return diff === 0;
}

